/// <summary>
///     The <c>AVASalesPackingSlipJournalCreateCls_Extension</c> class is the extension for <c>SalesPackingSlipJournalCreate</c>
/// </summary>
[ExtensionOf(classStr(SalesPackingSlipJournalCreate))]
final class AVASalesPackingSlipJournalCreateCls_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>initHeader</c> method.
/// </summary>
public void initHeader()
{
    next initHeader();

    if(this.parmInterCompanyPosted())
    {
        SalesTable locSalesTableIC = custPackingSlipJour.avaInterCompanySalesTable();

        changecompany(locSalesTableIC.DataAreaId)
        {
            custPackingSlipJour.PrintMgmtSiteId = locSalesTableIC.avaLastPackinglipRecord().PrintMgmtSiteId;
        }
    }
}

/// <summary>
///    AVA <c>initJournalHeader</c> method.
/// </summary>
protected void initJournalHeader()
{
    custPackingSlipJour locCustPackingSlipJour = custPackingSlipJour;

    next initJournalHeader();

    if(!locCustPackingSlipJour
        && this.parmInterCompanyPosted())
    {
        SalesTable locSalesTableIC = custPackingSlipJour.avaInterCompanySalesTable();

        changecompany(locSalesTableIC.DataAreaId)
        {
            custPackingSlipJour.PrintMgmtSiteId = locSalesTableIC.avaLastPackinglipRecord().PrintMgmtSiteId;
        }
    }
}

/// <summary>
/// next setDeliveryFields
/// </summary>
protected void setDeliveryFields()
{
    SalesParmLine       salesParmLine;

    next setDeliveryFields();

    select firstonly salesParmLine
        where salesParmLine.ParmId     == salesParmTable.ParmId
        &&    salesParmLine.TableRefId == salesParmTable.TableRefId;

    SalesLine localSalesLine = salesParmLine.salesLine();

    if(localSalesLine.interCompanySalesLine().RecId != 0)
    {
        localSalesLine = localSalesLine.interCompanySalesLine();
    }

    if(custPackingSlipJour.DlvMode != localSalesLine.DlvMode)
    {
        custPackingSlipJour.DlvMode           = localSalesLine.DlvMode;
    }
}
